let current=Number.isInteger(saved.current)&&saved.current>=0&&saved.current<5?saved.current:0,order=[],history=[],selected=null,moveCount=0,sound=false,audio=null,hintDepth=0,hintRule=0,drag=null,suppressClick=false,noticeTimer;
