function shuffle(){let a=Array.from({length:current===0?6:current===2?8:9},(_,i)=>i);do{for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]]}}while(PuzzleRules.check(current,a).some(Boolean));return a}
