function load(i){current=i;order=shuffle();history=[];selected=null;moveCount=0;hintDepth=0;drag=null;$('chapter-label').textContent=`0${i+1} / 05 — ${levels[i].en}`;$('title').textContent=levels[i].title;$('material').textContent=levels[i].material;$('hint-panel').hidden=true;$('result').hidden=true;refreshNav();render();persist()}
